const cfg = {
  nanomdmUrl: 'http://mdm-nanomdm.mdm.svc.cluster.local:9000',
  ntfyUrl: 'http://ntfy.ntfy.svc.cluster.local',
  ntfyTopic: 'Home-Lab-MDM'
};
return [{ json: cfg }];

const crypto = require('crypto');
const head = '<?xml version="1.0" encoding="UTF-8"?>\n'
  + '<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">\n'
  + '<plist version="1.0">\n<dict>\n\t<key>Command</key>\n\t<dict>\n';
const tail = (commandUuid) => '\t</dict>\n\t<key>CommandUUID</key>\n\t<string>' + commandUuid + '</string>\n</dict>\n</plist>\n';
const escapeXml = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');
const rows = $input.all().map((item) => item.json).filter((row) => row.enrollment_id);
if (rows.length === 0) return [{ json: { skip: true, silent: true } }];
const allowedRaw = $('Erlaubt-Liste lesen').first().json.allowed;
const allowed = new Set(Array.isArray(allowedRaw) ? allowedRaw : (typeof allowedRaw === 'string' ? JSON.parse(allowedRaw) : []));
if (!allowed.has('com.apple.Preferences') || !allowed.has('com.apple.AppStore')) {
  return [{ json: { skip: true, silent: false, priority: 'high', title: 'Aufraeumen abgebrochen', message: 'Die Erlaubt-Liste (Profil app-allowlist) ist unvollstaendig, es wurde nichts entfernt.' } }];
}
const unescapeXml = (value) => value.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&amp;/g, '&');
const parseApps = (plist) => {
  const apps = [];
  const dicts = String(plist).match(/<dict>(?:(?!<dict>)[\s\S])*?<\/dict>/g) || [];
  for (const dict of dicts) {
    const id = dict.match(/<key>Identifier<\/key>\s*<string>([^<]+)<\/string>/);
    if (!id) continue;
    const name = dict.match(/<key>Name<\/key>\s*<string>([^<]*)<\/string>/);
    apps.push({ id: unescapeXml(id[1]), name: name ? unescapeXml(name[1]) : unescapeXml(id[1]) });
  }
  return apps;
};
const notRemovable = new Set(['com.apple.camera', 'com.apple.mobilephone', 'com.apple.MobileSMS']);
const commands = [];
const issues = [];
const checked = [];
for (const row of rows) {
  const serial = row.serial_number || row.enrollment_id;
  if (row.status !== 'Acknowledged') {
    issues.push(serial + ': Inventur fehlgeschlagen (' + row.status + ')');
    continue;
  }
  const apps = parseApps(row.result);
  if (apps.length === 0) {
    issues.push(serial + ': keine App-Liste empfangen');
    continue;
  }
  checked.push(serial);
  for (const app of apps.filter((entry) => !allowed.has(entry.id) && !notRemovable.has(entry.id))) {
    const commandUuid = crypto.randomUUID();
    const plist = head
      + '\t\t<key>Identifier</key>\n\t\t<string>' + escapeXml(app.id) + '</string>\n'
      + '\t\t<key>RequestType</key>\n\t\t<string>RemoveApplication</string>\n'
      + tail(commandUuid);
    commands.push({ json: { skip: false, enrollment_id: row.enrollment_id, serial_number: serial, app: app.name, bundle_id: app.id, command_uuid: commandUuid, plist, issues, checked } });
  }
}
if (commands.length === 0) {
  const lines = [];
  if (checked.length > 0) lines.push('Auf ' + checked.join(', ') + ' ist nichts ausserhalb der Erlaubt-Liste installiert.');
  if (issues.length > 0) lines.push('Probleme: ' + issues.join('; ') + '.');
  return [{ json: { skip: true, silent: false, priority: issues.length > 0 ? 'high' : 'default', title: issues.length > 0 ? 'Aufraeumen mit Problemen' : 'iPads sind aufgeraeumt', message: lines.join(' ') } }];
}
return commands;

const built = $('Entfernen bauen').all().map((item) => item.json);
if (built[0].skip === true) {
  return [{ json: { silent: built[0].silent === true, title: built[0].title, message: built[0].message, priority: built[0].priority || 'default' } }];
}
const results = $input.all().map((response, index) => {
  const source = built[index];
  const body = response.json.body || {};
  const queued = body.command_uuid === source.command_uuid;
  return { serial: source.serial_number, app: source.app, queued, detail: queued ? '' : String(response.json.statusCode || response.json.error || 'keine Antwort') };
});
const failed = results.filter((row) => !row.queued);
const bySerial = {};
for (const row of results.filter((entry) => entry.queued)) (bySerial[row.serial] = bySerial[row.serial] || []).push(row.app);
const lines = [];
for (const serial of Object.keys(bySerial)) lines.push(serial + ': ' + bySerial[serial].join(', ') + ' (' + bySerial[serial].length + ').');
const issues = built[0].issues || [];
const lead = 'Zum Entfernen eingereiht: ' + (lines.join(' ') || 'nichts') ;
const extra = [];
if (failed.length > 0) extra.push('Nicht eingereiht: ' + failed.map((row) => row.serial + '/' + row.app + ' (' + row.detail + ')').join(', ') + '.');
if (issues.length > 0) extra.push('Probleme: ' + issues.join('; ') + '.');
const good = failed.length === 0 && issues.length === 0;
return [{ json: { silent: false, title: good ? 'Apps werden entfernt' : 'Apps entfernen mit Problemen', message: [lead].concat(extra).join(' '), priority: good ? 'default' : 'high' } }];
